def weave(self, signal, context):
    a = torch.sin(torch.cos(torch.relu(signal)))
    b = torch.cos(torch.tanh(torch.sin(signal)))
    c = torch.relu(torch.sin(torch.cos(signal)))
    f = torch.cat((a, b, c), dim=-1)
    if context is not None:
        f = f * context
        f = f + context
    return torch.tanh(f)

